const fs = require('node:fs');
const V = (m) => { console.error('CI_PERMISSIONS_FLOOR_VIOLATION: ' + m); process.exit(1); };
const H = (m) => { console.error('CI_PERMISSIONS_FLOOR_HARNESS_ERROR: ' + m); process.exit(2); };

function topLevelPermissions(text) {
  const lines = text.split(/\r?\n/);
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const bare = /^permissions:\s*(read-all|write-all)\s*(#.*)?$/.exec(line);
    if (bare) return { __bare: bare[1] };
    const empty = /^permissions:\s*\{\s*\}\s*(#.*)?$/.exec(line);
    if (empty) return {};
    if (/^permissions:\s*(#.*)?$/.test(line)) {
      const scopes = {};
      let j = i + 1;
      while (j < lines.length) {
        const l = lines[j];
        if (l.trim() === '' || /^\s*#/.test(l)) { j++; continue; }
        const m = /^(\s+)([A-Za-z0-9_-]+):\s*([A-Za-z0-9_-]+)\s*(#.*)?$/.exec(l);
        if (!m || m[1].length === 0) break;
        scopes[m[2]] = m[3];
        j++;
      }
      return scopes;
    }
  }
  return null;
}

try {
  const files = JSON.parse(process.argv[1]);
  const problems = [];
  for (const f of files) {
    let text;
    try { text = fs.readFileSync(f, 'utf8'); }
    catch (e) {
      if (e && e.code === 'ENOENT') { problems.push(f + ': file does not exist'); continue; }
      H('cannot read ' + f + ': ' + (e && e.message));
    }
    const perms = topLevelPermissions(text);
    if (perms === null) { problems.push(f + ': no top-level permissions: key'); continue; }
    if (perms.__bare) { problems.push(f + ': top-level permissions is bare "' + perms.__bare + '", not an explicit least-privilege map'); continue; }
    if (perms.contents !== 'read') { problems.push(f + ': top-level permissions.contents is "' + (perms.contents || '<absent>') + '", expected "read"'); continue; }
    const writeScopes = Object.entries(perms).filter(([k, v]) => v === 'write' || v === 'admin');
    if (writeScopes.length > 0) { problems.push(f + ': top-level permissions grants write/admin scope(s) [' + writeScopes.map(([k]) => k).join(',') + '] -- elevated scopes must stay job-level only'); continue; }
  }
  if (problems.length > 0) V('workflow(s) missing a safe least-privilege top-level permissions floor: ' + problems.join(' | '));
  console.log('CI_PERMISSIONS_FLOOR_OK: all ' + files.length + ' workflow files declare a safe top-level permissions floor (contents: read, no top-level write/admin scope)');
} catch (e) { H('unexpected: ' + (e && e.stack ? e.stack : e)); }

